CREATE TABLE projects (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL CHECK(project_id=id), name TEXT NOT NULL CHECK(length(trim(name))>0), description TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('active','archived')), version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
-- Registry stores only identity/type/ownership for polymorphic foreign keys.
-- Research content lives exclusively in dedicated tables below.
CREATE TABLE entity_registry (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL, UNIQUE(id,project_id,kind));
CREATE TABLE research_questions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','active','answered','archived')),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE TABLE sources (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,source_kind TEXT NOT NULL CHECK(source_kind IN ('pdf','url','doi','web_page','local_file','dataset','book','manual')),locator TEXT NOT NULL,checksum TEXT,metadata TEXT NOT NULL CHECK(json_valid(metadata)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE TABLE papers (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,publication_year INTEGER CHECK(publication_year BETWEEN 1 AND 9999),doi TEXT,abstract_text TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE TABLE paper_authors (paper_id TEXT NOT NULL REFERENCES papers(id),position INTEGER NOT NULL CHECK(position>=0),name TEXT NOT NULL,PRIMARY KEY(paper_id,position));
CREATE TABLE paper_sources (project_id TEXT NOT NULL REFERENCES projects(id),paper_id TEXT NOT NULL,source_id TEXT NOT NULL,PRIMARY KEY(paper_id,source_id),FOREIGN KEY(paper_id,project_id) REFERENCES papers(id,project_id),FOREIGN KEY(source_id,project_id) REFERENCES sources(id,project_id));
CREATE TABLE claims (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),paper_id TEXT NOT NULL,source_id TEXT,text TEXT NOT NULL,normalized_text TEXT,location_page INTEGER CHECK(location_page>0),location_section TEXT,location_paragraph INTEGER,location_text_span TEXT,location_offset INTEGER,location_table TEXT,location_figure TEXT,created_by TEXT NOT NULL CHECK(json_valid(created_by)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(paper_id,project_id) REFERENCES papers(id,project_id),FOREIGN KEY(source_id,project_id) REFERENCES sources(id,project_id),FOREIGN KEY(paper_id,source_id) REFERENCES paper_sources(paper_id,source_id));
CREATE TABLE hypotheses (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),question_id TEXT,title TEXT NOT NULL,statement TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','proposed','active','supported','rejected','inconclusive','archived')),confidence REAL CHECK(confidence BETWEEN 0 AND 1),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(question_id,project_id) REFERENCES research_questions(id,project_id));
CREATE TABLE experiments (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),hypothesis_id TEXT NOT NULL,title TEXT NOT NULL,objective TEXT NOT NULL,methodology TEXT NOT NULL,protocol TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','proposed','approved','ready','running','completed','failed','cancelled','archived')),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(hypothesis_id,project_id) REFERENCES hypotheses(id,project_id));
CREATE TABLE tasks (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed','cancelled')),created_by TEXT NOT NULL CHECK(json_valid(created_by)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE TABLE runs (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT NOT NULL,parent_run_id TEXT,status TEXT NOT NULL CHECK(status IN ('pending','running','waiting_for_human','completed','failed','cancelled')),started_at TEXT,finished_at TEXT,error TEXT,provider_metadata TEXT NOT NULL CHECK(json_valid(provider_metadata)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id),FOREIGN KEY(parent_run_id,project_id) REFERENCES runs(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE artifacts (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,artifact_kind TEXT NOT NULL CHECK(artifact_kind IN ('dataset','csv','figure','notebook','code','report','output','document')),path TEXT NOT NULL,content_hash TEXT NOT NULL CHECK(length(content_hash)=64),byte_size INTEGER NOT NULL CHECK(byte_size>=0),metadata TEXT NOT NULL CHECK(json_valid(metadata)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE UNIQUE INDEX artifacts_active_path ON artifacts(project_id,path) WHERE archived=0;
CREATE TABLE experiment_runs (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),experiment_id TEXT NOT NULL,run_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('running','completed','failed','cancelled')),started_at TEXT NOT NULL,finished_at TEXT,metadata TEXT NOT NULL CHECK(json_valid(metadata)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(experiment_id,project_id) REFERENCES experiments(id,project_id),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id));
CREATE TABLE experiment_run_artifacts (experiment_run_id TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id),artifact_id TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('input','output')),position INTEGER NOT NULL CHECK(position>=0),PRIMARY KEY(experiment_run_id,direction,position),FOREIGN KEY(experiment_run_id,project_id) REFERENCES experiment_runs(id,project_id),FOREIGN KEY(artifact_id,project_id) REFERENCES artifacts(id,project_id));
CREATE TABLE findings (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),experiment_run_id TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,confidence REAL CHECK(confidence BETWEEN 0 AND 1),created_by TEXT NOT NULL CHECK(json_valid(created_by)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(experiment_run_id,project_id) REFERENCES experiment_runs(id,project_id));
CREATE TABLE relations (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),from_id TEXT NOT NULL,from_kind TEXT NOT NULL,to_id TEXT NOT NULL,to_kind TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('contains','derived_from','supports','contradicts','qualifies','addresses','related_to','tests','produced','uses','references','based_on','supersedes')),confidence REAL CHECK(confidence BETWEEN 0 AND 1),created_by TEXT NOT NULL CHECK(json_valid(created_by)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(from_id,project_id,from_kind) REFERENCES entity_registry(id,project_id,kind),FOREIGN KEY(to_id,project_id,to_kind) REFERENCES entity_registry(id,project_id,kind));
CREATE UNIQUE INDEX relations_active_unique ON relations(project_id,from_id,to_id,kind) WHERE archived=0;
CREATE INDEX relations_from ON relations(project_id,from_id);
CREATE INDEX relations_to ON relations(project_id,to_id);
CREATE TABLE gates (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','expired','cancelled')),proposed_action TEXT NOT NULL CHECK(json_valid(proposed_action)),affected_entities TEXT NOT NULL CHECK(json_valid(affected_entities)),expected_versions TEXT NOT NULL CHECK(json_valid(expected_versions)),reason TEXT NOT NULL,risk TEXT NOT NULL,created_by TEXT NOT NULL CHECK(json_valid(created_by)),run_id TEXT,resolved_at TEXT,resolved_by TEXT CHECK(resolved_by IS NULL OR json_valid(resolved_by)),result TEXT CHECK(result IS NULL OR json_valid(result)),version INTEGER NOT NULL CHECK(version>0),archived INTEGER NOT NULL CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id),CHECK((status='pending' AND resolved_at IS NULL AND resolved_by IS NULL) OR (status!='pending' AND resolved_at IS NOT NULL AND resolved_by IS NOT NULL)));
CREATE UNIQUE INDEX gates_action_unique ON gates(project_id,json_extract(proposed_action,'$.id'));
CREATE TABLE action_receipts (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),action TEXT NOT NULL CHECK(json_valid(action)),result TEXT NOT NULL CHECK(json_valid(result)));
CREATE TABLE domain_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),event_type TEXT NOT NULL,schema_version INTEGER NOT NULL CHECK(schema_version>0),actor TEXT NOT NULL CHECK(json_valid(actor)),run_id TEXT,correlation_id TEXT,causation_id TEXT,occurred_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id));
CREATE TABLE provenance_records (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),actor TEXT NOT NULL CHECK(json_valid(actor)),action TEXT NOT NULL,entity TEXT CHECK(entity IS NULL OR json_valid(entity)),run_id TEXT,gate_id TEXT REFERENCES gates(id),reason TEXT NOT NULL,source_entities TEXT NOT NULL CHECK(json_valid(source_entities)),event_id TEXT NOT NULL REFERENCES domain_events(id),created_at TEXT NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id));
CREATE INDEX events_project_time ON domain_events(project_id,occurred_at,sequence);
CREATE INDEX provenance_project_entity ON provenance_records(project_id,json_extract(entity,'$.id'));
CREATE INDEX runs_project_status ON runs(project_id,status);
CREATE INDEX gates_project_status ON gates(project_id,status);
CREATE INDEX claims_paper ON claims(paper_id);
CREATE INDEX experiments_hypothesis ON experiments(hypothesis_id);
CREATE INDEX questions_project ON research_questions(project_id);
CREATE INDEX sources_project ON sources(project_id);
CREATE INDEX papers_project ON papers(project_id);
CREATE INDEX hypotheses_project ON hypotheses(project_id);
CREATE INDEX experiment_runs_project ON experiment_runs(project_id);
CREATE INDEX findings_project ON findings(project_id);
CREATE INDEX artifacts_project ON artifacts(project_id);
CREATE INDEX tasks_project ON tasks(project_id);
-- History is append-only, including for direct SQL maintenance operations.
CREATE TRIGGER events_no_update BEFORE UPDATE ON domain_events BEGIN SELECT RAISE(ABORT,'domain events are immutable'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON domain_events BEGIN SELECT RAISE(ABORT,'domain events are immutable'); END;
CREATE TRIGGER provenance_no_update BEFORE UPDATE ON provenance_records BEGIN SELECT RAISE(ABORT,'provenance is immutable'); END;
CREATE TRIGGER provenance_no_delete BEFORE DELETE ON provenance_records BEGIN SELECT RAISE(ABORT,'provenance is immutable'); END;
